CREATE FUNCTION public.can_use_workbench(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_admin(_user_id) OR public.has_role(_user_id, 'sales_agent') OR public.has_role(_user_id, 'operations_agent') $$;
CREATE TABLE public.workbench_threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), mailbox text NOT NULL CHECK(mailbox IN ('sales','ops')), gmail_thread_id text NOT NULL, subject text NOT NULL DEFAULT '', from_name text, from_email text, snippet text, message_count integer NOT NULL DEFAULT 0, last_message_at timestamptz, in_inbox boolean NOT NULL DEFAULT true, lead_id uuid REFERENCES public.leads(id), yt_ref text, ball text NOT NULL DEFAULT 'ours' CHECK(ball IN ('ours','client','supplier')), urgency text NOT NULL DEFAULT 'week' CHECK(urgency IN ('urgent','today','week')), urgency_reason text, ai_reading text, ai_checked text, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(mailbox,gmail_thread_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.workbench_threads TO authenticated; GRANT ALL ON public.workbench_threads TO service_role;
ALTER TABLE public.workbench_threads ENABLE ROW LEVEL SECURITY;
CREATE POLICY workbench_threads_access ON public.workbench_threads TO authenticated USING(public.can_use_workbench(auth.uid())) WITH CHECK(public.can_use_workbench(auth.uid()));
CREATE TABLE public.workbench_checklist (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.leads(id), item_key text NOT NULL, label text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('ok','pending','missing','na')), source text NOT NULL DEFAULT 'auto' CHECK(source IN ('auto','manual')), note text, updated_by uuid, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(lead_id,item_key));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.workbench_checklist TO authenticated; GRANT ALL ON public.workbench_checklist TO service_role;
ALTER TABLE public.workbench_checklist ENABLE ROW LEVEL SECURITY;
CREATE POLICY workbench_checklist_access ON public.workbench_checklist TO authenticated USING(public.can_use_workbench(auth.uid())) WITH CHECK(public.can_use_workbench(auth.uid()));
CREATE TABLE public.workbench_settings (key text PRIMARY KEY, value jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.workbench_settings TO authenticated; GRANT ALL ON public.workbench_settings TO service_role;
ALTER TABLE public.workbench_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY workbench_settings_read ON public.workbench_settings FOR SELECT TO authenticated USING(public.can_use_workbench(auth.uid()));
CREATE POLICY workbench_settings_admin ON public.workbench_settings FOR ALL TO authenticated USING(public.is_admin(auth.uid())) WITH CHECK(public.is_admin(auth.uid()));
CREATE TABLE public.workbench_alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.leads(id), side text NOT NULL CHECK(side IN ('sales','ops')), title text NOT NULL, reason text NOT NULL, next_step text, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','snoozed','handled')), snoozed_until timestamptz, created_at timestamptz NOT NULL DEFAULT now(), handled_at timestamptz, handled_by uuid);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.workbench_alerts TO authenticated; GRANT ALL ON public.workbench_alerts TO service_role;
ALTER TABLE public.workbench_alerts ENABLE ROW LEVEL SECURITY;
CREATE POLICY workbench_alerts_access ON public.workbench_alerts TO authenticated USING(public.can_use_workbench(auth.uid())) WITH CHECK(public.can_use_workbench(auth.uid()));
CREATE UNIQUE INDEX workbench_alerts_open_reason ON public.workbench_alerts(lead_id,side,reason) WHERE status <> 'handled';
CREATE TABLE public.workbench_auto_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.leads(id), side text NOT NULL CHECK(side IN ('sales','ops')), what text NOT NULL, trace text, reversible boolean NOT NULL DEFAULT false, created_by_agent text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.workbench_auto_log TO authenticated; GRANT ALL ON public.workbench_auto_log TO service_role;
ALTER TABLE public.workbench_auto_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY workbench_auto_log_read ON public.workbench_auto_log FOR SELECT TO authenticated USING(public.can_use_workbench(auth.uid()));
CREATE POLICY workbench_auto_log_insert ON public.workbench_auto_log FOR INSERT TO authenticated WITH CHECK(public.can_use_workbench(auth.uid()));
CREATE FUNCTION public.workbench_set_auto_checklist(p_lead_id uuid,p_item_key text,p_label text,p_status text,p_note text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN INSERT INTO public.workbench_checklist(lead_id,item_key,label,status,source,note,updated_by) VALUES(p_lead_id,p_item_key,p_label,p_status,'auto',p_note,auth.uid()) ON CONFLICT(lead_id,item_key) DO UPDATE SET label=excluded.label,status=excluded.status,note=excluded.note,updated_at=now() WHERE workbench_checklist.source='auto'; END $$;
REVOKE ALL ON FUNCTION public.workbench_set_auto_checklist(uuid,text,text,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.workbench_set_auto_checklist(uuid,text,text,text,text) TO authenticated,service_role;
CREATE INDEX workbench_threads_pending ON public.workbench_threads(mailbox,in_inbox,last_message_at);
CREATE INDEX workbench_checklist_lead ON public.workbench_checklist(lead_id);
CREATE INDEX workbench_auto_log_recent ON public.workbench_auto_log(side,created_at DESC);